'use client';

import React, { useState } from 'react';
import Navbar from '@/components/layout/Navbar';
import FileDropzone from '@/components/upload/FileDropzone';
import { profileFile } from '@/lib/profiler';
import { ArrowRight } from 'lucide-react';
import ReportCanvas from './canvas/ReportCanvas';
import DataTable from '@/components/ui/DataTable';

export default function Dashboard() {
    const [step, setStep] = useState<'upload' | 'profiling' | 'canvas'>('upload');
    const [view, setView] = useState<'stats' | 'preview'>('preview');
    const [dataset, setDataset] = useState<any>(null);
    const [isProfiling, setIsProfiling] = useState(false);

    const handleFileSelect = async (file: File) => {
        setIsProfiling(true);
        try {
            const profile = await profileFile(file);
            setDataset({ name: file.name, ...profile });
            setStep('profiling');
        } catch (err) {
            console.error('Error profiling file:', err);
            alert('Failed to process file. Check console for details.');
        } finally {
            setIsProfiling(false);
        }
    };

    return (
        <div className="main-container">
            <Navbar />

            <main style={{ flex: 1, padding: '40px 24px', maxWidth: '1400px', margin: '0 auto', width: '100%' }}>
                {step === 'upload' && (
                    <div style={{ marginTop: '100px', textAlign: 'center' }}>
                        <h2 style={{ fontSize: '2.5rem', marginBottom: '40px' }} className="gradient-text">
                            {isProfiling ? 'Profiling your data...' : 'Ready to start?'}
                        </h2>
                        <FileDropzone onFileSelect={handleFileSelect} />
                    </div>
                )}

                {step === 'profiling' && dataset && (
                    <div className="animate-in fade-in duration-500">
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '32px' }}>
                            <div>
                                <h2 style={{ fontSize: '1.5rem', marginBottom: '8px' }}>{dataset.name}</h2>
                                <div style={{ display: 'flex', gap: '12px' }}>
                                    <button
                                        onClick={() => setView('preview')}
                                        style={{
                                            background: view === 'preview' ? 'var(--surface)' : 'transparent',
                                            padding: '4px 12px',
                                            borderRadius: '6px',
                                            color: view === 'preview' ? 'var(--accent)' : 'var(--text-muted)',
                                            fontSize: '0.875rem',
                                            border: 'none',
                                            cursor: 'pointer'
                                        }}
                                    >
                                        Preview
                                    </button>
                                    <button
                                        onClick={() => setView('stats')}
                                        style={{
                                            background: view === 'stats' ? 'var(--surface)' : 'transparent',
                                            padding: '4px 12px',
                                            borderRadius: '6px',
                                            color: view === 'stats' ? 'var(--accent)' : 'var(--text-muted)',
                                            fontSize: '0.875rem',
                                            border: 'none',
                                            cursor: 'pointer'
                                        }}
                                    >
                                        Statistics
                                    </button>
                                </div>
                            </div>
                            <button
                                className="btn-primary"
                                style={{ padding: '12px 24px', display: 'flex', alignItems: 'center', gap: '8px' }}
                                onClick={() => setStep('canvas')}
                            >
                                Create Report <ArrowRight size={18} />
                            </button>
                        </div>

                        {view === 'stats' ? (
                            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
                                {dataset.stats.map((col: any) => (
                                    <div key={col.column} className="glass-card" style={{ padding: '20px' }}>
                                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '16px' }}>
                                            <span style={{ fontWeight: 600, color: 'var(--accent)' }}>{col.column}</span>
                                            <span style={{ fontSize: '0.75rem', opacity: 0.6, background: 'var(--surface)', padding: '2px 8px', borderRadius: '4px' }}>
                                                {col.type}
                                            </span>
                                        </div>

                                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                                            <div>
                                                <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Unique</p>
                                                <p style={{ fontWeight: 500 }}>{col.unique}</p>
                                            </div>
                                            <div>
                                                <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Nulls</p>
                                                <p style={{ fontWeight: 500 }}>{col.nulls}</p>
                                            </div>
                                            {col.min != null && (
                                                <div style={{ gridColumn: 'span 2' }}>
                                                    <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Range</p>
                                                    <p style={{ fontWeight: 500, fontSize: '0.875rem' }}>{col.min} - {col.max}</p>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <DataTable columns={dataset.columns} data={dataset.preview} />
                        )}
                    </div>
                )}

                {step === 'canvas' && dataset && (
                    <ReportCanvas dataset={dataset} />
                )}
            </main>
        </div>
    );
}
